import{_ as a,o as r,c as i,ai as t}from"./chunks/framework.lvpqbiZd.js";const p=JSON.parse('{"title":"Asumi Premium Hero Redesign Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-08-31-asumi-premium-hero-redesign.md","filePath":"superpowers/plans/2026-08-31-asumi-premium-hero-redesign.md"}'),s={name:"superpowers/plans/2026-08-31-asumi-premium-hero-redesign.md"};function n(l,e,o,d,c,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="asumi-premium-hero-redesign-implementation-plan" tabindex="-1">Asumi Premium Hero Redesign Implementation Plan <a class="header-anchor" href="#asumi-premium-hero-redesign-implementation-plan" aria-label="Permalink to “Asumi Premium Hero Redesign Implementation Plan”">​</a></h1><blockquote><p><strong>For agentic workers:</strong> REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (<code>- [ ]</code>) syntax for tracking.</p></blockquote><p><strong>Goal:</strong> Deliver a focused premium Asumi loader and Hero with a natural fabric-light surface and corrected brand hierarchy.</p><p><strong>Architecture:</strong> OGL renders a lightweight full-screen Strands loader. React Three Fiber renders the Hero&#39;s decorative horizon, hairline orbits, layered shader surfaces, and particles while React DOM/GSAP owns all text and sequencing.</p><p><strong>Tech Stack:</strong> React 19, TypeScript, GSAP, OGL, Three.js, React Three Fiber, Vitest, CSS</p><h2 id="global-constraints" tabindex="-1">Global Constraints <a class="header-anchor" href="#global-constraints" aria-label="Permalink to “Global Constraints”">​</a></h2><ul><li>Build only the loader and Hero in this phase.</li><li>Keep the existing SVG scene as a reduced-motion and WebGL fallback, but restyle it to match the same visual hierarchy.</li><li>Keep <code>/desk</code>, <code>/dashboard</code>, and <code>/api</code> unchanged.</li><li>Preserve lazy loading and cap WebGL DPR at <code>1.5</code>.</li></ul><hr><h3 id="task-1-lock-the-brand-frame-with-tests" tabindex="-1">Task 1: Lock The Brand Frame With Tests <a class="header-anchor" href="#task-1-lock-the-brand-frame-with-tests" aria-label="Permalink to “Task 1: Lock The Brand Frame With Tests”">​</a></h3><ul><li>[ ] Update tests to require <code>آینده‌ای روشن</code>, a loading status, the Hero host, and no <code>What We Build</code> section.</li><li>[ ] Run the focused tests and confirm they fail before implementation.</li></ul><h3 id="task-2-add-the-strands-loader" tabindex="-1">Task 2: Add The Strands Loader <a class="header-anchor" href="#task-2-add-the-strands-loader" aria-label="Permalink to “Task 2: Add The Strands Loader”">​</a></h3><ul><li>[ ] Install <code>ogl</code> and local variable fonts.</li><li>[ ] Add a typed <code>Strands</code> component with resize, visibility pause, reduced-motion handling, and WebGL cleanup.</li><li>[ ] Add the Asumi loading veil and an inline pre-React fallback.</li><li>[ ] Re-run focused tests.</li></ul><h3 id="task-3-replace-line-geometry-with-surface-shaders" tabindex="-1">Task 3: Replace Line Geometry With Surface Shaders <a class="header-anchor" href="#task-3-replace-line-geometry-with-surface-shaders" aria-label="Permalink to “Task 3: Replace Line Geometry With Surface Shaders”">​</a></h3><ul><li>[ ] Remove tube ribbons and circular sun geometry.</li><li>[ ] Add anisotropic horizon and reflection shaders.</li><li>[ ] Add layered subdivided fabric planes with vertex displacement and rim-light alpha.</li><li>[ ] Replace torus meshes with offset hairline orbit loops and keep particles behind the content.</li></ul><h3 id="task-4-correct-hierarchy-and-motion" tabindex="-1">Task 4: Correct Hierarchy And Motion <a class="header-anchor" href="#task-4-correct-hierarchy-and-motion" aria-label="Permalink to “Task 4: Correct Hierarchy And Motion”">​</a></h3><ul><li>[ ] Remove the temporary lower section and pill CTA.</li><li>[ ] Apply local Manrope and Vazirmatn variable fonts.</li><li>[ ] Sequence the approved reveal only after the loader exits.</li><li>[ ] Keep the complete composition static for reduced motion and mobile fallback.</li></ul><h3 id="task-5-verify-and-deliver" tabindex="-1">Task 5: Verify And Deliver <a class="header-anchor" href="#task-5-verify-and-deliver" aria-label="Permalink to “Task 5: Verify And Deliver”">​</a></h3><ul><li>[ ] Run the complete test suite, typecheck, and production build.</li><li>[ ] Verify generated assets and live root, admin, dashboard, and API routes.</li><li>[ ] Commit and push the source on the current server branch.</li></ul>',18)])])}const u=a(s,[["render",n]]);export{p as __pageData,u as default};
